-- Minimal isolated PostgreSQL schema for applying and exercising the real
-- estoque_comando_idempotente migration. No production data is loaded.
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'anon') THEN
        CREATE ROLE anon NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'authenticated') THEN
        CREATE ROLE authenticated NOLOGIN;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'service_role') THEN
        CREATE ROLE service_role NOLOGIN;
    END IF;
END
$$;

CREATE SCHEMA IF NOT EXISTS extensions;
CREATE OR REPLACE FUNCTION extensions.uuid_generate_v5(uuid, text) RETURNS uuid
LANGUAGE sql IMMUTABLE AS $$ SELECT md5($1::text || ':' || $2)::uuid $$;
CREATE OR REPLACE FUNCTION extensions.digest(bytea, text) RETURNS bytea
LANGUAGE sql IMMUTABLE AS $$
    SELECT decode(md5($1::text || ':' || $2), 'hex')
        || decode(md5('sha256:' || $1::text || ':' || $2), 'hex')
$$;

DROP TABLE IF EXISTS public.eventos_auditoria CASCADE;
DROP TABLE IF EXISTS public.demanda_estoque_processado CASCADE;
DROP TABLE IF EXISTS public.demanda_alocacoes_estoque CASCADE;
DROP TABLE IF EXISTS public.demandas_pedidos CASCADE;
DROP TABLE IF EXISTS public.itens_demanda CASCADE;
DROP TABLE IF EXISTS public.demandas_producao CASCADE;
DROP TABLE IF EXISTS public.estoque_operacoes CASCADE;
DROP TABLE IF EXISTS public.movimentacoes_estoque CASCADE;
DROP TABLE IF EXISTS public.estoque_atual CASCADE;
DROP TABLE IF EXISTS public.produtos CASCADE;
DROP TABLE IF EXISTS public.depositos CASCADE;

CREATE TABLE public.produtos (
    id integer PRIMARY KEY,
    nome text
);

CREATE TABLE public.depositos (
    id integer PRIMARY KEY
);

CREATE TABLE public.demandas_producao (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    demanda_id varchar(255) NOT NULL UNIQUE,
    status varchar(80) DEFAULT 'PENDENTE',
    escopo_despacho jsonb DEFAULT '{}'::jsonb,
    updated_at timestamptz DEFAULT now()
);

CREATE TABLE public.itens_demanda (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    demanda_id integer NOT NULL REFERENCES public.demandas_producao(id),
    produto_id integer REFERENCES public.produtos(id),
    quantidade numeric
);

CREATE TABLE public.demandas_pedidos (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    demanda_id integer NOT NULL REFERENCES public.demandas_producao(id),
    pedido_id bigint NOT NULL
);

CREATE TABLE public.estoque_atual (
    produto_id integer NOT NULL REFERENCES public.produtos(id),
    deposito_id integer NOT NULL REFERENCES public.depositos(id),
    saldo_atual numeric(15,4) NOT NULL DEFAULT 0,
    reservado numeric(15,4) NOT NULL DEFAULT 0,
    ultima_atualizacao timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    disponivel numeric(15,4) GENERATED ALWAYS AS (saldo_atual - reservado) STORED,
    CONSTRAINT estoque_atual_produto_id_deposito_id_key UNIQUE (produto_id, deposito_id)
);

CREATE TABLE public.movimentacoes_estoque (
    id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    produto_id integer NOT NULL REFERENCES public.produtos(id),
    deposito_id integer NOT NULL REFERENCES public.depositos(id),
    tipo_movimentacao varchar(50) NOT NULL,
    quantidade numeric(15,4) NOT NULL,
    saldo_antes numeric(15,4),
    saldo_depois numeric(15,4),
    documento_referencia varchar(255),
    motivo text,
    usuario_id integer,
    item_demanda_id integer REFERENCES public.itens_demanda(id),
    produto_nome varchar(255),
    data_movimentacao timestamp without time zone DEFAULT CURRENT_TIMESTAMP,
    correlation_id uuid,
    origem_tipo integer,
    estagio text
);

-- Active Supabase types: business IDs stay varchar while product/deposit IDs
-- and movement links use the internal integer keys confirmed in the catalog.
CREATE TABLE public.demanda_alocacoes_estoque (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    demanda_id varchar(255) NOT NULL,
    item_id varchar(255) NOT NULL,
    produto_id varchar(255) NOT NULL,
    correlation_id varchar(100) NOT NULL,
    quantidade_alocada numeric(10,2) NOT NULL DEFAULT 0,
    tipo_alocacao varchar(50) NOT NULL,
    processo_origem varchar(50),
    status varchar(20) DEFAULT 'PENDENTE',
    metadata jsonb DEFAULT '{}'::jsonb,
    created_at timestamptz DEFAULT now(),
    processed_at timestamptz,
    cancelled_at timestamptz,
    CONSTRAINT demanda_alocacoes_fixture_status_check
        CHECK (status IN ('PENDENTE', 'PROCESSADA', 'CANCELADA')),
    CONSTRAINT demanda_alocacoes_fixture_quantity_check CHECK (quantidade_alocada >= 0)
);

CREATE TABLE public.demanda_estoque_processado (
    id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    item_id integer NOT NULL REFERENCES public.itens_demanda(id),
    demanda_id integer NOT NULL REFERENCES public.demandas_producao(id),
    estagio varchar(80) NOT NULL,
    quantidade numeric NOT NULL,
    saldo_acumulado numeric NOT NULL,
    correlation_id varchar(255),
    tipo_movimentacao varchar(80) NOT NULL DEFAULT 'CONS_MP',
    produto_id integer,
    created_at timestamptz DEFAULT now()
);

CREATE TABLE public.eventos_auditoria (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tipo_evento varchar(120) NOT NULL,
    descricao text,
    registro_id integer,
    dados_novos jsonb,
    created_at timestamptz DEFAULT now()
);

-- Minimal signatures referenced by the permissions migration. Only the
-- cancellation RPC is replaced with its real implementation under test.
CREATE OR REPLACE FUNCTION public.despacho_cancelar_demanda(integer, text, text)
RETURNS TABLE(out_demanda_codigo text, out_pedidos_devolvidos integer, out_estornos_estoque integer)
LANGUAGE sql AS $$ SELECT NULL::text, 0, 0 $$;
